import SnapshotTesting
import SwiftUI
import XCTest
@testable import Pulseline

final class WorkoutSummaryViewSnapshotTests: XCTestCase {
    private let view = WorkoutSummaryView(summary: .fixture5k)

    func testLight() {
        assertSnapshot(of: view, as: .image(layout: .device(config: .iPhone13), traits: .init(userInterfaceStyle: .light)))
    }
    func testDark() {
        assertSnapshot(of: view, as: .image(layout: .device(config: .iPhone13), traits: .init(userInterfaceStyle: .dark)))
    }
    func testAccessibilityXXXL() {
        assertSnapshot(of: view, as: .image(layout: .device(config: .iPhone13), traits: .init(preferredContentSizeCategory: .accessibilityExtraExtraExtraLarge)))
    }
}
